<template><AppLayout page-title="Rendez-vous"><div class="toolbar"><RouterLink class="btn btn-primary" to="/appointments/new">+ Prendre un rendez-vous</RouterLink></div><div v-if="loading" class="loading-overlay"><div class="spinner"/></div><div v-else class="card"><div v-if="items.length===0" class="empty-state"><div class="empty-icon">📅</div><div class="empty-title">Aucun rendez-vous</div></div><div v-for="a in items" :key="a.id" class="list-row"><div><b>Dr. {{a.doctor?.first_name}} {{a.doctor?.last_name}}</b><div>{{new Date(a.scheduled_at).toLocaleString('fr-FR')}}</div><small>{{a.reason_for_visit}}</small></div><RouterLink v-if="['confirmed','requested'].includes(a.status)" class="btn btn-primary btn-sm" :to="`/care-forms/${a.id}`">Fiche de soins</RouterLink><span class="badge" :class="badge(a.status)">{{a.status}}</span><button v-if="['requested','confirmed'].includes(a.status)" class="btn btn-ghost btn-sm" @click="cancel(a.id)">Annuler</button></div></div></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {RouterLink} from 'vue-router';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';const auth=useAuthStore();const items=ref<any[]>([]),loading=ref(true);const badge=(s:string)=>({confirmed:'badge-green',requested:'badge-blue',cancelled:'badge-red',completed:'badge-neutral'}[s]||'badge-neutral');async function load(){if(!auth.user)return;const {data}=await supabase.from('appointments').select('*,doctor:profiles!appointments_doctor_id_fkey(first_name,last_name)').eq('patient_id',auth.user.id).order('scheduled_at',{ascending:false});items.value=data||[];loading.value=false}async function cancel(id:string){if(!confirm('Annuler ce rendez-vous ?'))return;await supabase.from('appointments').update({status:'cancelled',cancellation_reason:'Annulé par le patient',cancelled_by:auth.user?.id,cancelled_at:new Date().toISOString()}).eq('id',id);await load()}onMounted(load)</script>
